    /// 给定一个字符串 s 和一个字符串数组 words。 words 中所有字符串 长度相同。
    ///
    ///  s 中的 串联子串 是指一个包含  words 中所有字符串以任意顺序排列连接起来的子串。
    ///
    /// 例如，如果 words = ["ab","cd","ef"]， 那么 "abcdef"， "abefcd"，"cdabef"， "cdefab"，"efabcd"， 和 "efcdab" 都是串联子串。 "acdbef" 不是串联子串，因为他不是任何 words 排列的连接。
    ///
    /// 返回所有串联子串在 s 中的开始索引。你可以以 任意顺序 返回答案。
    /// ```
    /// 1 <= s.length <= 10⁴
    /// 1 <= words.length <= 5000
    /// 1 <= words[i].length <= 30
    /// words[i] 和 s 由小写英文字母组成
    ///```
    public List<Integer> findSubstring(String s, String[] words) {
        final int length = s.length();
        if (length < words.length * words[0].length()) {
            return new ArrayList<>();
        }
        List<Integer> result = new ArrayList<>();
        int wordsLength = words.length, wordLength = words[0].length();

        final Map<String, Integer> sWords = new HashMap<>();
        for (String string : words) {
            if (sWords.containsKey(string)) {
                sWords.put(string, sWords.get(string) + 1);
            } else {
                sWords.put(string, 1);
            }
        }

        for (int i = 0; i < wordLength; i++) {
            Map<String, Integer> tmpWords = new HashMap<>(sWords);
            String s1;

            //first word check
            int left = i, last = i + wordsLength * wordLength - 1;
            if (last >= length) {
                break; // 如果右边界超出字符串长度，直接跳出循环
            }
            for (int j = 0; j < wordsLength; j++) {
                s1 = s.substring(left, left + wordLength);
                left += wordLength;
                if (!sWords.containsKey(s1)) {
                    continue;
                }
                tmpWords.put(s1, tmpWords.getOrDefault(s1, 0) - 1);
                if (tmpWords.get(s1) == 0) {
                    tmpWords.remove(s1);
                }
            }
            //first word match
            if (tmpWords.isEmpty()) {
                result.add(i);
            }

            // windows slip, second+ word check
            left = i;
            last = i + wordsLength * wordLength - 1;
            while (last < length) {
                //remove left
                s1 = s.substring(left, left + wordLength);
                if (sWords.containsKey(s1)) {
                    tmpWords.put(s1, tmpWords.getOrDefault(s1, 0) + 1);
                    if (tmpWords.get(s1) == 0) {
                        tmpWords.remove(s1);
                    }
                }

                // move one word
                left += wordLength;
                last += wordLength;
                if (last >= length) {
                    break; // 如果右边界超出字符串长度，直接跳出循环
                }

                //right
                s1 = s.substring(last - wordLength + 1, last + 1);
                if (!sWords.containsKey(s1)) {
                    continue;
                }
                tmpWords.put(s1, tmpWords.getOrDefault(s1, 0) - 1);
                if (tmpWords.get(s1) == 0) {
                    tmpWords.remove(s1);
                }

                //word match
                if (tmpWords.isEmpty()) {
                    result.add(left);
                }
            }

        }

        return result;
    }

    public List<Integer> findSubstring0(String s, String[] words) {
        if (s.length() < words.length * words[0].length()) {
            return new ArrayList<>();
        }
        List<Integer> result = new ArrayList<>();
        int wordsLength = words.length, wordLength = words[0].length();

        final Map<String, Integer> sWords = new HashMap<>();
        for (String string : words) {
            if (sWords.containsKey(string)) {
                sWords.put(string, sWords.get(string) + 1);
            } else {
                sWords.put(string, 1);
            }
        }

        for (int i = 0; i < s.length(); i++) {
            Map<String, Integer> tmpWords = new HashMap<>(sWords);
            int left = i, right = i + wordLength, last = i + wordsLength * wordLength;
            if (last > s.length()) {
                break; // 如果右边界超出字符串长度，直接跳出循环
            }

            boolean isAllTrue = true;
            String s1;
            for (int j = 0; j < wordsLength; j++) {
                s1 = s.substring(left, right);
                if (!tmpWords.containsKey(s1)) {
                    isAllTrue = false;
                    break;
                }
                tmpWords.put(s1, tmpWords.get(s1) - 1);
                left += wordLength;
                right += wordLength;
            }
            if (!isAllTrue) {
                continue; // 如果当前子串不满足条件，跳过后续检查
            }

            for (String word : words) {
                if (tmpWords.get(word) != 0) {
                    isAllTrue = false;
                    break;
                }
            }
            if (isAllTrue) {
                result.add(i);
            }
        }

        return result;
    }
